import{H as e,V as t,et as n,j as r}from"./chunks/framework.CW0zsFMp.js";import{$o as i,Jo as a,Ko as o,Qo as s,Xo as c,Yo as l,Zo as u,as as d,cs as f,es as p,is as m,ns as h,os as g,qo as _,rs as v,ss as y,ts as b}from"./chunks/assets.BxHYjuf8.js";var x=JSON.parse(`{"title":"InnoDB引擎","description":"","frontmatter":{},"headers":[],"relativePath":"mysql/innodb-engine.md","filePath":"mysql/innodb-engine.md"}`),S={name:`mysql/innodb-engine.md`};function C(r,x,S,C,w,T){return n(),t(`div`,null,[...x[0]||=[e(`<h1 id="innodb引擎" tabindex="-1">InnoDB引擎 <a class="header-anchor" href="#innodb引擎" aria-label="Permalink to “InnoDB引擎”">​</a></h1><h2 id="_1-逻辑存储结构" tabindex="-1">1.逻辑存储结构 <a class="header-anchor" href="#_1-逻辑存储结构" aria-label="Permalink to “1.逻辑存储结构”">​</a></h2><p><img src="`+f+`" alt="8880195f3eba4a20acd448c70f11ceddpng" width="892" height="456"></p><p><strong>表空间（ibd文件）</strong>：一个mysql实例可以对应多个表空间，用于存储记录、索引等数据。</p><p><strong>段</strong>：分为数据段（Leaf node segment）、索引段（Non-leaf node segment）、回滚段（Rollback segment），InnoDB 是索引组织表，数据段就是B+树的叶子节点， 索引段即为B+树的非叶子节点。段用来管理多个Extent（区）。</p><p><strong>区</strong>：表空间的单元结构，每个区的大小为1M。 默认情况下， InnoDB存储引擎页大小为16K， 即一个区中一共有64个连续的页。</p><p><strong>页</strong>：是InnoDB 存储引擎磁盘管理的最小单元，每个页的大小默认为 16KB。为了保证页的连续性，InnoDB 存储引擎每次从磁盘申请 4-5 个区。</p><p><strong>行</strong>：InnoDB 存储引擎数据是按行进行存放的。</p><ul><li><p><code>Trx_id</code>：每次对某条记录进行改动时，都会把对应的事务id赋值给trx_id隐藏列。</p></li><li><p><code>Roll_pointer</code>：每次对某条引记录进行改动时，都会把旧的版本写入到undo日志中，然后这个隐藏列就相当于一个指针，可以通过它来找到该记录修改前的信息。</p></li></ul><h2 id="_2-架构" tabindex="-1">2.架构 <a class="header-anchor" href="#_2-架构" aria-label="Permalink to “2.架构”">​</a></h2><p>MySQL5.5 版本开始，默认使用InnoDB存储引擎，它擅长事务处理，具有崩溃恢复特性，在日常开发中使用非常广泛。下面是InnoDB架构图，左侧为内存结构，右侧为磁盘结构：</p><p><img src="`+y+`" alt="cd42e56b86224b508aaf93f830319433png" width="1205" height="845"></p><h3 id="_2-1-内存架构" tabindex="-1">2.1 内存架构 <a class="header-anchor" href="#_2-1-内存架构" aria-label="Permalink to “2.1 内存架构”">​</a></h3><p><img src="`+g+`" alt="3da849e70e8341bcb957cc5113fe0b39png" width="1232" height="494"></p><p><img src="`+d+`" alt="cfa82fb3bc8e4fb1a79e45a0931c9f3apng" width="1518" height="737"></p><p><img src="`+m+`" alt="d2a4bea099004d949351caa74b4695ccpng" width="1515" height="640"></p><ul><li><code>adaptive_hash_index</code>：控制是否启用自适应哈希索引，ON表示开启，OFF表示关闭，默认值是ON；具体操作参考系统变量。</li></ul><p><img src="`+v+`" alt="6c5ede0ada414783970593771b5c8b39png" width="1521" height="613"></p><h3 id="_2-2-磁盘结构" tabindex="-1">2.2 磁盘结构 <a class="header-anchor" href="#_2-2-磁盘结构" aria-label="Permalink to “2.2 磁盘结构”">​</a></h3><p><img src="`+h+`" alt="19f7a298c5994c1ab4109818c9fce57cpng" width="1906" height="888"></p><ul><li><code>innodb_data_file_path</code>：用于定义InnoDB的系统表空间（System Tablespace）的文件路径、大小和属性。</li></ul><p><img src="`+b+`" alt="ad3a644bf18a4099a5aa1d3d25e5cab4png" width="949" height="204"></p><ul><li><code>innodb_file_per_table</code>：控制InnoDB是否为每个表创建独立的表空间文件，ON表示每个表都有自己的表空间文件，OFF表示所有表的数据和索引存储在系统表空间中，默认值是ON。</li></ul><p><img src="`+p+`" alt="4db5fa41656747189db99f89bcbe62depng" width="1539" height="612"></p><p>通用表空间：将多个表的数据存储在一个共享的文件中，方便管理和维护。</p><p>创建通用表空间文件</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> TABLESPACE</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tablespace_name</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">ADD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DATAFILE </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;file_name.ibd&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[FILE_BLOCK_SIZE = value]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[ENGINE </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">[</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=] InnoDB];</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tablespace_name：通用表空间的名称</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">file_name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ibd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">：表空间文件的路径和名称，要确保指定的文件路径是MySQL可访问的，并且有足够的权限</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FILE_BLOCK_SIZE：可选参数，指定表空间的文件块大小（通常与表的页大小一致），必须与表的页大小一致（例如16K）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ENGINE：指定存储引擎，默认为 InnoDB。</span></span></code></pre></div><p>创建表时指定表空间</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ...[TABLESPACE tablespace_name];</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tablespace_name：指定表存储的通用表空间名称</span></span></code></pre></div><p>将现有表移动到通用表空间</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">ALTER</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> table_name TABLESPACE tablespace_name;</span></span></code></pre></div><p>删除通用表空间</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">DROP</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SPACE tablespace_name;</span></span></code></pre></div><p><img src="`+i+`" alt="4205f8ee3dec4bb1abdd9f119d4678e3png" width="1559" height="635"></p><h3 id="_2-3-后台线程" tabindex="-1">2.3 后台线程 <a class="header-anchor" href="#_2-3-后台线程" aria-label="Permalink to “2.3 后台线程”">​</a></h3><p><img src="`+s+`" alt="bc4aca94694b4ce4920517f41bf6c8dbpng" width="1472" height="714"></p><h2 id="_3-事务原理" tabindex="-1">3.事务原理 <a class="header-anchor" href="#_3-事务原理" aria-label="Permalink to “3.事务原理”">​</a></h2><p>特性原理分类图：</p><p><img src="`+u+`" alt="94ac6ad8c8c24e4f91f540f55ef9cfdcpng" width="1477" height="545"></p><ul><li>原子性通过undo log日志实现，持久性通过redo log日志实现，一致性通过undo log和redo log两个日志实现，隔离性通过锁和MVCC实现</li></ul><h3 id="_3-1-redo-log" tabindex="-1">3.1 redo log <a class="header-anchor" href="#_3-1-redo-log" aria-label="Permalink to “3.1 redo log”">​</a></h3><p>重做日志，记录的是事务提交时数据页的物理修改，是用来实现事务的<strong>持久性</strong>。</p><p>该日志文件由两部分组成:重做日志缓冲(redo log buffer)以及重做日志文件(redo log file)，前者是在内存中，后者在磁盘中。当事务提交之后会把所有修改信息都存到该日志文件中,用于在刷新脏页到磁盘,发生错误时,进行数据恢复使用。</p><p>Buffer Pool在产生脏页数据的时候，会先将数据存储到 redo log buffer 再存储到 redo log 中进行磁盘持久化存储，在内存出现异常（比如突然断电）时，通过redo log中持久化的数据进行回滚。过程如下图：</p><p><img src="`+c+`" alt="3560cee853f944bd95dd5f6fabe1c864png" width="1486" height="506"></p><p>当用户执行UPDATE或DELETE操作时，数据页会被加载到内存的Buffer Pool中进行修改，同时生成Redo Log记录并暂存于Redo Log Buffer中。事务提交时，Redo Log Buffer中的日志会先写入磁盘的Redo Log文件（ib_logfile0/1），确保事务的持久性，而数据页的修改则通过后台线程异步刷入磁盘的表空间文件（.ibd）。这种WAL机制保证了即使系统崩溃，也能通过Redo Log恢复未刷盘的数据变更，从而确保数据的一致性和持久性。</p><p>问题：数据为什么要通过redolog写入ibd表空间文件，而不是直接从Buffer Pool直接刷新到磁盘ibd文件？</p><p>答：Buffer Pool 刷盘是<strong>随机写</strong>：数据页在磁盘上的位置是分散的、随机的，每次刷盘都需要寻址，性能较低。Redo Log 是<strong>顺序写</strong>：每次写入都是追加到日志文件的末尾，性能非常高。</p><h3 id="_3-2-undo-log" tabindex="-1">3.2 undo log <a class="header-anchor" href="#_3-2-undo-log" aria-label="Permalink to “3.2 undo log”">​</a></h3><p>回滚日志，用于记录数据被修改前的信息，作用包含：提供回滚 和 MVCC(多版本并发控制)。</p><p>undo log 和 redo log 记录物理日志不一样，它是逻辑日志。可以认为当 delete 一条记录时，undo log中会记录一条对应的insert记录，反之亦然，当 update 一条记录时，它记录一条对应相反的 update 记录。当执行 rollback 时，就可以从 undo log 中的逻辑记录读取到相应的内容并进行回滚。</p><ul><li><p>Undo log 销毁：undo log 在事务执行时产生，事务提交时，并不会立即删除undol0g，因为这些日志可能还用于 MVCC</p></li><li><p>Undo log 存储：undo log 采用段的方式进行管理和记录，存放在前面介绍的 rollback segment 回滚段中，内部包含1024个 undo log segment</p></li></ul><h3 id="_3-3-mvcc" tabindex="-1">3.3 MVCC <a class="header-anchor" href="#_3-3-mvcc" aria-label="Permalink to “3.3 MVCC”">​</a></h3><h4 id="_3-3-1-基本概念" tabindex="-1">3.3.1 基本概念 <a class="header-anchor" href="#_3-3-1-基本概念" aria-label="Permalink to “3.3.1 基本概念”">​</a></h4><p><strong>当前读</strong>：读取的是记录的最新版本，读取时还要保证其他并发事务不能修改当前记录，会对读取的记录进行加锁。对于我们日常的操作，如:select…lock in share mode(共享锁)，select… for update、update、insert、delete(排他锁)都是一种当前读</p><p><strong>快照读</strong>：简单的select(不加锁)就是快照读，快照读，读取的是记录数据的可见版本，有可能是历史数据，不加锁，是非阻塞读</p><ul><li><p>Read committed：每次select，都生成一个快照读</p></li><li><p>Repeatable Read：开启事务后第一个select语句才是快照读的地方</p></li><li><p>Serializable：快照读会退化为当前读</p></li></ul><p><strong>MVCC</strong>：全称 Multi-Version Concurrency Control，多版本并发控制。指维护一个数据的多个版本，使得读写操作没有冲突，快照读为MySQL实现MVCC提供了一个非阻塞读功能。MVCC的具体实现，还需要依赖于数据库记录中的三个隐式字段、undo log日志、read View</p><h4 id="_3-3-2-记录中的隐藏字段" tabindex="-1">3.3.2 记录中的隐藏字段 <a class="header-anchor" href="#_3-3-2-记录中的隐藏字段" aria-label="Permalink to “3.3.2 记录中的隐藏字段”">​</a></h4><p>每一张创建的表都有两个或三个隐藏字段：DB_TRX_ID、DB_ROOL_PRT、DB_ROW_ID（表没有主键时存在）</p><p><img src="`+l+`" alt="ee88721b01924efba50f5d263fdb719epng" width="1499" height="574"></p><h4 id="_3-3-3-undo-log" tabindex="-1">3.3.3 undo log <a class="header-anchor" href="#_3-3-3-undo-log" aria-label="Permalink to “3.3.3 undo log”">​</a></h4><p>回滚日志，在insert、update、delete的时候产生的便于数据回滚的日志。</p><p>当insert的时候，产生的undoloq日志只在回滚时需要，在事务提交后，可被立即删除。</p><p>当update、delete的时候，产生的undo log日志不仅在回滚时需要，在快照读时也需要，不会立即被删除。</p><p>那么何时删除？</p><ul><li>当所有依赖于该undo log的快照读取操作结束后，undo log才会被删除。这意味着如果有一个事务正在进行快照读取，并且依赖于某个undo log，那么这个undo log会一直保留直到该事务结束。</li></ul><p><strong>undo log版本链</strong>：</p><p><img src="`+a+`" alt="836d4b592dcd4b4094d3dc6813dacf34png" width="1511" height="614"></p><h4 id="_3-3-4-readview" tabindex="-1">3.3.4 readview <a class="header-anchor" href="#_3-3-4-readview" aria-label="Permalink to “3.3.4 readview”">​</a></h4><p>ReadView(读视图)是 快照读 SQL执行时MVCC提取数据的依据，记录并维护系统当前活跃的事务(未提交的)id</p><p>ReadView中包含了四个核心字段：</p><table tabindex="0"><thead><tr><th>字段</th><th>含义</th></tr></thead><tbody><tr><td>m_ids</td><td>当前活跃的事务ID集合</td></tr><tr><td>min_trx_id</td><td>最小活跃事务ID</td></tr><tr><td>max_trx_id</td><td>预分配事务ID，当前最大事务ID+1（因为事务ID是自增的）</td></tr><tr><td>creator_trx_id</td><td>ReadView创建者的事务ID</td></tr></tbody></table><p><img src="`+_+`" alt="227674f068f94104b9620d2d97c15881png" width="1521" height="695"></p><p><strong>READ COMMITTED</strong></p><p><img src="`+o+`" alt="316de3cd29944939b6477ee57d70c376png" width="1508" height="674"></p><p>针对事务5的两条查询语句，第一条查询语句：记录一次ReadView读视图，拿着当前事务id即DB_TRX_ID=4根据版本链数据访问规则依次判断，判断到第4条发现trx_id=4在集合m_ids中，在链表结构找到下一个DB_TRX_ID=3，再次进行判断，发现3仍然在集合m_ids中，再次在链表结构找到下一个DB_TRX_ID=2，发现满足第2条规则，所以查询到0x00002指向的记录（id: 30, age: 3, name: A30）;</p><p>事务5的第二条查询语句重新记录一次ReadView读视图，然后根据新的ReadView读视图重新判断，直到找到满足版本链数据访问规则的一条版本记录为止，所以两次查询结果不一定一致</p><p><strong>REPEATBLE READ</strong></p><p>查询过程和READ COMMITTED相同，只是事务5的第二条查询语句不会重新生成ReadView读视图，会复用第一条查询语句的ReadView读视图，所以两次查询的结果一致</p>`,80)]])}var w=r(S,[[`render`,C]]);export{x as __pageData,w as default};